import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        int odd = 0, even = 0;
        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            if ((x & 1L) == 0) even++;
            else odd++;
        }

        // Each action reduces the number of balls by 1.
        // We can continue while both odd and even exist.
        // To maximize actions:
        // - Use (odd, even) pairs as much as possible: each keeps both parities present
        //   and changes counts as odd--, even unchanged.
        // - This can be done until odd becomes 0.
        // - If even > 0 and odd == 0, then all remaining are even, so stop.
        //
        // If initially odd <= even:
        //   We can do exactly odd actions, then all remaining are even.
        //
        // If initially odd > even:
        //   After even cross-parity actions, counts become:
        //     odd = odd - even, even = even
        //   Now odd > 0 and even > 0 still hold.
        //   We can continue using pairs of odd balls:
        //     odd -= 2, even += 1
        //   until odd becomes 1 if odd-even is odd, or 0 if even.
        //   To avoid ending with all odd too early, maximum total actions becomes:
        //     even + floor((odd - even) / 2)
        //
        // This simplifies to:
        //   if (odd <= even) ans = odd;
        //   else ans = even + (odd - even) / 2;
        long ans;
        if (odd <= even) ans = odd;
        else ans = even + (odd - even) / 2;

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

