#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    long long odd = 0, even = 0;
    for (int i = 0; i < N; ++i) {
        long long x;
        cin >> x;
        if (x & 1) odd++;
        else even++;
    }

    // An action is possible iff there is at least one odd and one even ball.
    // To maximize the number of actions:
    // - Pair odd+even -> produces odd, counts decrease as (odd, even) -> (odd, even-1)
    //   so this can be repeated until no even remains.
    // - If initially odd=0 or even=0, no action is possible.
    // Therefore maximum actions = number of even balls when odd>0, else 0.
    long long ans = (odd > 0 && even > 0) ? even : 0;
    cout << ans << '\n';
    return 0;
}

#include <stdio.h>

int main() {
    int N;
    scanf("%d", &N);
    int odd = 0, even = 0;
    for (int i = 0; i < N; i++) {
        int a;
        scanf("%d", &a);
        if (a % 2 == 0) even++;
        else odd++;
    }
    int actions = 0;
    while (1) {
        if (odd >= 2) {
            odd -= 2;
            even++;
            actions++;
        } else if (odd >= 1 && even >= 1) {
            odd--; // actually odd stays same: remove odd+even -> add odd
            even--;
            actions++;
        } else if (even >= 2) {
            even--;
            actions++;
        } else {
            break;
        }
    }
    printf("%d\n", actions);
    return 0;
}

#include <stdio.h>
int main() {
    int n, o = 0, e = 0, x;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) { scanf("%d", &x); if (x%2) o++; else e++; }
    int ans = 0;
    while (o > 0 && e > 0) { ans++; e--; }
    while (o >= 2) { ans += 2; o -= 2; e = 0; /* odd+odd->even, then even+odd->odd */ }
    // actually after odd+odd we get e=1, then odd+even->odd, e=0 again
    printf("%d\n", ans);
}

#include <stdio.h>

int main(void) {
    long long N, x;
    long long odd = 0, even = 0;

    if (scanf("%lld", &N) != 1) return 0;

    for (long long i = 0; i < N; i++) {
        scanf("%lld", &x);
        if (x & 1) odd++;
        else even++;
    }

    /* 
       An action is possible iff there is at least one odd and one even ball.
       To continue as long as possible, always merge:
       - odd + odd -> even, if odd >= 2
       - even + even -> even, if even >= 2 and odd == 1

       This leads to:
       - if odd == 0: 0
       - if odd is even: N - 1
       - if odd is odd : N - 2
    */

    long long ans;
    if (odd == 0) ans = 0;
    else if (odd % 2 == 0) ans = N - 1;
    else ans = N - 2;

    if (ans < 0) ans = 0;
    printf("%lld\n", ans);
    return 0;
}
